import itertools

def get_next_states(grid, rows, cols):
    next_states = []
    for r in range(rows - 1):
        for c in range(cols - 1):
            block = [grid[r][c], grid[r+1][c], grid[r][c+1], grid[r+1][c+1]]
            s = sum(block)
            if s == 3:
                # Rule 1: the one sterile section becomes infected
                new_grid = [list(row) for row in grid]
                for dr, dc in [(0,0), (1,0), (0,1), (1,1)]:
                    if new_grid[r+dr][c+dc] == 0:
                        new_grid[r+dr][c+dc] = 1
                next_states.append(tuple(tuple(row) for row in new_grid))
            elif s == 2:
                # Rule 2: flip all 4
                new_grid = [list(row) for row in grid]
                for dr, dc in [(0,0), (1,0), (0,1), (1,1)]:
                    new_grid[r+dr][c+dc] = 1 - new_grid[r+dr][c+dc]
                next_states.append(tuple(tuple(row) for row in new_grid))
    return next_states

def can_reach_all_ones(start_grid, rows, cols):
    visited = {start_grid}
    stack = [start_grid]
    target = tuple(tuple([1]*cols) for _ in range(rows))

    while stack:
        curr = stack.pop()
        if curr == target:
            return True
        for nxt in get_next_states(curr, rows, cols):
            if nxt not in visited:
                visited.add(nxt)
                stack.append(nxt)
    return False

def solve_for_grid(rows, cols):
    for k in range(rows * cols + 1):
        all_reachable = True
        # We need to check all configurations of size k
        # This is too many for 4x4, but we can try for 2x2, 3x3
        import itertools
        all_cells = [(r, c) for r in range(rows) for c in range(cols)]
        for combo in itertools.combinations(all_cells, k):
            grid = [[0]*cols for _ in range(rows)]
            for r, c in combo:
                grid[r][c] = 1
            start_grid = tuple(tuple(row) for row in grid)
            if not can_reach_all_ones(start_grid, rows, cols):
                all_reachable = False
                break
        if all_reachable:
            return k
    return None

